public class Compiler_getState_TriageGen1Test {

    private Compiler compiler;

    @Before
    public void setUp() {
        compiler = new Compiler();
    }

    @Test
    public void testGetState_DefaultValues() {
        // Test the initial state with default null/empty values
        IntermediateState state = compiler.getState();

        assertNotNull(state);
        assertNull(state.externsRoot);
        assertNull(state.jsRoot);
        assertNull(state.externs);
        assertNull(state.inputs);
        assertNull(state.modules);
        assertNull(state.typeRegistry);
        // normalized is a boolean, default is false
        assertEquals(false, state.normalized);
    }

    @Test
    public void testGetState_WithPopulatedFields() {
        // Prepare mock/real objects for the fields
        JSSourceFile extern = JSSourceFile.parse("extern.js", "var x = 1;");
        JSSourceFile input = JSSourceFile.parse("input.js", "var y = 2;");
        CompilerOptions options = new CompilerOptions();
        PassConfig passConfig = new PassConfig();

        // To satisfy getPassConfig().getIntermediateState(), 
        // we need to initialize the compiler with options and a pass config.
        compiler.init(new JSSourceFile[]{extern}, new JSSourceFile[]{input}, options);
        compiler.setPassConfig(passConfig);

        // Simulate normalization
        compiler.normalize();

        // Execute
        IntermediateState state = compiler.getState();

        // Verify
        assertNotNull(state);
        assertEquals(extern, state.externsRoot); // In init, externsRoot is often set via the provided externs
        assertEquals(input, state.jsRoot);      // In init, jsRoot is often set via the provided inputs
        assertEquals(1, state.externs.length);
        assertEquals(1, state.inputs.length);
        assertNotNull(state.passConfigState);
        assertNotNull(state.typeRegistry);
        assertTrue(state.normalized);
    }

    @Test
    public void testGetState_WithModules() {
        // Prepare module-based setup
        JSModule module = new JSModule("module", "var m = 1;");
        CompilerOptions options = new CompilerOptions();

        // Using the init method that accepts modules
        compiler.init(new JSSourceFile[0], new JSModule[]{module}, options);

        // Execute
        IntermediateState state = compiler.getState();

        // Verify
        assertNotNull(state);
        assertEquals(1, state.modules.length);
        assertEquals(module, state.modules[0]);
    }

    @Test
    public void testGetState_AfterSetState() {
        // This tests if the state returned is a new object containing the current field values,
        // even if we manually set a state via setState (though getState doesn't use the setState value directly,
        // it builds a new one from the compiler's internal fields).

        IntermediateState manualState = new IntermediateState();
        manualState.normalized = true;

        // Note: The implementation of getState() in the provided snippet 
        // constructs a NEW IntermediateState and copies fields from the compiler.
        // It does NOT return the object passed to setState().

        compiler.setState(manualState);
        IntermediateState returnedState = compiler.getState();

        // Since getState() creates a new instance and copies fields from the compiler's fields,
        // and setState() usually updates those fields, we check for consistency.
        // If setState updates the compiler's internal fields:
        assertNotNull(returnedState);
    }
}
